// ─────────────────────────────────────────────────────────────────
// Construye el payload para DeepSeek con system prompt + historia
// ─────────────────────────────────────────────────────────────────
const input = $input.first().json.body || $input.first().json;
const userMessage = (input.message || '').toString().slice(0, 1000);
const history = Array.isArray(input.history) ? input.history.slice(-10) : [];
const userName = input.userName || 'cliente';

const SYSTEM_PROMPT = `Eres BarberBot, el asistente virtual oficial de la barbería **BarberSchedule**. Tu objetivo es ayudar a los clientes a agendar citas, conocer servicios, y resolver dudas sobre la barbería.

# TONO Y ESTILO
- Habla en **español mexicano casual** pero profesional. Tutea al usuario.
- Sé **breve y amigable**. Mensajes de 2-4 oraciones máximo.
- Usa **1-2 emojis** por mensaje, no más.
- Si el usuario escribe en **inglés u otro idioma**, responde en ese mismo idioma.
- Adapta tu tono: si es joven/casual, sé relajado; si es formal, sé más serio.

# CATÁLOGO DE SERVICIOS (usa estos precios, no inventes)
- **Corte clásico** (id=1) — 30 min — $120
- **Corte degradado** (id=2) — 30 min — $150  
- **Barba** (id=3) — 30 min — $100
- **Corte + barba** (id=4) — 45 min — $230
- **Tinte** (id=5) — 60 min — $350
- **Diseño** (id=6) — 45 min — $200

# EQUIPO DE BARBEROS
- **Carlos Ruiz** (id=1) — Clásico, 5 años de experiencia
- **Miguel Ángel** (id=2) — Degradados, 7 años de experiencia
- **Luis Hernández** (id=3) — Diseños, 3 años de experiencia

# HORARIOS
- Lunes a viernes: 10:00 — 20:00
- Sábado: 10:00 — 18:00
- Domingo: cerrado

# UBICACIÓN Y CONTACTO
- Estamos en el centro de la ciudad. La dirección exacta se manda por WhatsApp al confirmar.
- WhatsApp: +52 555 010 1010
- Email: hola@barberschedule.app
- Formas de pago: efectivo, tarjeta débito/crédito, transferencia

# LO QUE PUEDES HACER
1. Responder sobre servicios, precios, barberos, horarios, ubicación, contacto
2. Recomendar servicios según lo que el usuario busca
3. Comparar opciones (ej: "¿qué diferencia hay entre fade bajo y medio?")
4. Ayudar a agendar (usar la herramienta bookService)
5. Responder dudas generales sobre cortes, mantenimiento, etc.
6. Detectar frustración y sugerir contacto humano

# LO QUE NO DEBES HACER
- No inventes precios, servicios o barberos
- No prometas descuentos no autorizados
- No des opiniones médicas o legales
- No hables de temas fuera de la barbería (si insisten, redirige amablemente)
- No des datos personales de otros clientes

# HERRAMIENTAS DISPONIBLES
Tienes 3 herramientas (function calling) que puedes usar cuando sea apropiado:
- **bookService**: cuando el usuario quiera agendar un servicio. Pasa el serviceId.
- **viewBarber**: cuando pregunten por un barbero específico. Pasa el barberId.
- **viewServices**: cuando pidan ver todos los servicios disponibles.

Cuando uses una herramienta, el sistema la ejecutará y te dará el resultado, luego tú lo presentarás al usuario de forma natural.

# INSTRUCCIONES DE USO DE HERRAMIENTAS
- Si el usuario dice algo como "quiero agendar corte clásico" → usa bookService(serviceId: 1)
- Si dice "me interesa el degradado, cuánto cuesta?" → responde el precio SIN usar herramienta, solo informativo
- Si pregunta "quién me puede atender?" → usa viewServices() o sugiere un barbero según la pregunta
- Si solo navega o pregunta, no uses herramientas innecesarias
- Las herramientas se usan SOLO cuando el usuario explícitamente quiere agendar o ver algo concreto

# INICIO DE CONVERSACIÓN
- Si es el primer mensaje, saluda cálidamente y pregunta en qué puedes ayudar
- Si el usuario ya escribió algo, responde directamente sin repetir el saludo

# FORMATO DE RESPUESTAS
- Texto plano, sin markdown complejo
- No uses ** para negritas dentro de tus respuestas (mejor usa MAYÚSCULAS si necesitas énfasis)
- Si listas servicios, sepáralos con saltos de línea

# FRASES ÚTILES PARA MEXICANOS
- "¡Qué onda!", "¡Hola! ¿Cómo te echamos la mano?"
- "Con gusto te ayudo"
- "¿Algo más en lo que te pueda ayudar?"
- "¡Nos vemos pronto! 💈"
`;

const messages = [
  { role: 'system', content: SYSTEM_PROMPT },
  ...history,
  { role: 'user', content: userMessage }
];

return {
  json: {
    model: 'deepseek-chat',
    messages,
    temperature: 0.7,
    max_tokens: 500,
    stream: false,
    tools: [
      {
        type: 'function',
        function: {
          name: 'bookService',
          description: 'Navega al formulario para agendar un servicio específico. Usar cuando el usuario quiera agendar una cita.',
          parameters: {
            type: 'object',
            properties: {
              serviceId: {
                type: 'number',
                description: 'ID del servicio: 1=Corte clásico, 2=Degradado, 3=Barba, 4=Corte+Barba, 5=Tinte, 6=Diseño',
                enum: [1, 2, 3, 4, 5, 6]
              },
              serviceName: {
                type: 'string',
                description: 'Nombre del servicio para confirmar'
              }
            },
            required: ['serviceId', 'serviceName']
          }
        }
      },
      {
        type: 'function',
        function: {
          name: 'viewBarber',
          description: 'Resalta la información de un barbero específico. Usar cuando pregunten por uno en particular.',
          parameters: {
            type: 'object',
            properties: {
              barberId: {
                type: 'number',
                description: 'ID del barbero: 1=Carlos, 2=Miguel Ángel, 3=Luis',
                enum: [1, 2, 3]
              },
              barberName: {
                type: 'string'
              }
            },
            required: ['barberId']
          }
        }
      },
      {
        type: 'function',
        function: {
          name: 'viewServices',
          description: 'Muestra la lista completa de servicios disponibles. Usar cuando pidan ver todos los servicios.',
          parameters: {
            type: 'object',
            properties: {}
          }
        }
      }
    ]
  }
};

// ─────────────────────────────────────────────────────────────────
// Procesa la respuesta de DeepSeek.
// Si llamó a una herramienta, la maneja aquí (en este caso, devuelve
// una acción que el frontend ejecuta).
// ─────────────────────────────────────────────────────────────────
const response = $input.first().json;
const choice = response.choices?.[0];
const message = choice?.message;

if (!message) {
  return {
    json: {
      text: 'Lo siento, tuve un problema al procesar tu mensaje. ¿Puedes intentar de nuevo?',
      action: null,
    }
  };
}

// ¿Llamó a una herramienta?
if (message.tool_calls && message.tool_calls.length > 0) {
  const toolCall = message.tool_calls[0];
  const fnName = toolCall.function.name;
  let args = {};
  try {
    args = JSON.parse(toolCall.function.arguments);
  } catch (e) {
    args = {};
  }

  let action = null;

  if (fnName === 'bookService' && args.serviceId) {
    action = {
      type: 'navigate',
      path: '/nueva-cita',
      queryParams: { service: args.serviceId },
      label: `Ir a agendar ${args.serviceName || 'el servicio'}`,
    };
  } else if (fnName === 'viewBarber' && args.barberId) {
    action = {
      type: 'navigate',
      path: '/barberos',
      queryParams: { highlight: args.barberId },
      label: `Ver perfil de ${args.barberName || 'el barbero'}`,
    };
  } else if (fnName === 'viewServices') {
    action = {
      type: 'navigate',
      path: '/servicios',
      label: 'Ver todos los servicios',
    };
  }

  // El bot probablemente incluyó un content también
  const text = message.content || '¡Va! Aquí te dejo lo que necesitas.';

  return {
    json: {
      text,
      action,
      toolUsed: fnName,
    }
  };
}

// Respuesta normal sin tool
return {
  json: {
    text: message.content || 'Lo siento, no entendí bien. ¿Me lo repites?',
    action: null,
  }
};
